def choose_move(observation):
    def sign(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pos_pair(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(src, dst):
        return [sign(dst[0] - src[0]), sign(dst[1] - src[1])]

    def step_away(src, dst):
        return [sign(src[0] - dst[0]), sign(src[1] - dst[1])]

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos_pair(observation.get("self_position", (0, 0)))
    ox, oy = pos_pair(observation.get("opponent_position", (sx, sy)))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)
    w = observation.get("grid_width", 0)
    h = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)

        corners = [(0, 0)]
        if h:
            corners.append((0, h - 1))
        if w:
            corners.append((w - 1, 0))
            if h:
                corners.append((w - 1, h - 1))
        if corners:
            target = max(corners, key=lambda c: manhattan(c, opp_pos))
            return step_toward(self_pos, target)
        return step_away(self_pos, opp_pos)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        if targets:
            best = min(targets, key=lambda p: (manhattan(pos_pair(p), self_pos), manhattan(pos_pair(p), opp_pos)))
            return step_toward(self_pos, pos_pair(best))
        # fallback: pressure opponent while avoiding direct overlap
        return step_away(self_pos, opp_pos) if manhattan(self_pos, opp_pos) <= 2 else step_toward(self_pos, opp_pos)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if resources:
        # Prefer resources that are closer to self and not much closer to the opponent.
        best = min(
            resources,
            key=lambda p: (
                manhattan(pos_pair(p), self_pos) - max(0, 2 - manhattan(pos_pair(p), opp_pos)),
                manhattan(pos_pair(p), opp_pos),
            ),
        )
        target = pos_pair(best)
        if manhattan(self_pos, opp_pos) <= 1 and manhattan(target, opp_pos) <= 1:
            return step_away(self_pos, opp_pos)
        return step_toward(self_pos, target)

    # Generic fallback: approach opponent if far, otherwise sidestep/escape.
    if manhattan(self_pos, opp_pos) <= 1:
        return step_away(self_pos, opp_pos)
    return step_toward(self_pos, opp_pos)

